from pvlib import tools
import numpy as np

def _obj_test_golden_sect(params, loc):
    return params[loc] * (1. - params['c'] * params[loc]**params['n'])

# Test case where upper == lower
params = {'c': 1., 'n': 1.}
lower = 0.5
upper = 0.5  # Same as lower
print('Testing with equal bounds...')
try:
    v, x = tools._golden_sect_DataFrame(params, lower, upper, _obj_test_golden_sect)
    print(f'Result: v={v}, x={x}')
except Exception as e:
    print(f'Error: {e}')
"
"}

